export const FIXTURE_INGREDIENTS: SuggestIngredient[] = ROWS.map(([name, size, unit, price, code, inc], i) => ({
  id: `ing-${i + 1}`,
  name,
  supplier_code: code ?? null,
  pack_size: size,
  pack_unit: unit,
  pack_price: price,
  price_inc_gst: inc ?? false,
  active: true,
}));

export const idOf = (name: string): string => {
  const hit = FIXTURE_INGREDIENTS.find((i) => i.name === name);
  if (!hit) throw new Error(`No fixture ingredient called ${name}`);
  return hit.id;
};

